    source_files: Mapping[str, str] | None = None
    validation: ValidationResult | None = None
    compile_flags: tuple[str, ...] = ()
    language: str | None = field(init=False)
    entry_point: str | None = field(init=False)
    output_style: OutputStyle | None = field(init=False)
    function: Callable[..., Any] | None = field(
        default=None, init=False, repr=False, compare=False
    )

    def __post_init__(self):
        object.__setattr__(self, "name", nonempty(self.name, "kernel name"))
        if not isinstance(self.problem, ProblemSpec):
            raise TypeError("kernel problem must be a ProblemSpec")
        if self.validation is not None and not isinstance(
            self.validation, ValidationResult
        ):
            raise TypeError("kernel validation must be a ValidationResult")
        object.__setattr__(self, "compile_flags", tuple(self.compile_flags))

        sources = {}
        for name, text in mapping(self.source_files or {}, "kernel source_files").items():
            path = relative_source_path(name, "kernel source path")
            if not isinstance(text, str):
                raise TypeError("kernel source contents must be strings")
            if "\x00" in text:
                raise ValueError("kernel sources must not contain NUL bytes")
            sources[path] = text
        object.__setattr__(self, "source_files", sources)
        self.read_build()

    def read_build(self):
        # A source-free placeholder carries only the problem contract. Its build
        # identity stays unknown until the caller supplies sources.
        if not self.source_files:
            for name in ("language", "entry_point", "output_style"):
                object.__setattr__(self, name, None)
            return

        if BUNDLE_CONFIG not in self.source_files:
            backend = get_backend(self.problem.language, self.problem.platform)
            object.__setattr__(self, "language", self.problem.language)
            object.__setattr__(
                self, "entry_point", f"{backend.raw_source}::klineage_launch"
            )
            object.__setattr__(self, "output_style", OutputStyle.DESTINATION)
            return

        config = tomllib.loads(self.source_files[BUNDLE_CONFIG])
        for name in self.source_files:
            if name != BUNDLE_CONFIG and not name.startswith(f"{BUNDLE_SOLUTION}/"):
                raise ValueError(
                    "bundles contain only config.toml and solution/ sources"
                )
        solution = mapping(config[BUNDLE_SOLUTION], "solution metadata")
        for key in ("name", "definition", "author"):
            nonempty(solution[key], f"solution {key}")
        build = mapping(config["build"], "build metadata")
        language = build["language"]
        suffixes = (".py",)
        if language != "python":
            backend = get_backend(self.problem.language, self.problem.platform)
            if language != backend.language:
                raise ValueError(
                    f"build language must be {backend.language} or python for {backend.kind}"
                )
            suffixes = backend.entry_suffixes
        entry = nonempty(build["entry_point"], "build entry_point")
        parts = entry.split("::")
        if entry != build["entry_point"] or len(parts) != 2:
            raise ValueError("entry_point must be relative/source::symbol")
        path, symbol = parts
        relative_source_path(path, "build entry source")
        if PurePosixPath(path).suffix not in suffixes:
            raise ValueError("entry source suffix is incompatible with build language")
        if not symbol.isidentifier() or keyword.iskeyword(symbol):
            raise ValueError("entry symbol must be an identifier")
        destination = build.get("destination_passing_style", False)
        if type(destination) is not bool:
            raise TypeError("destination_passing_style must be a boolean")
        object.__setattr__(self, "language", language)
        object.__setattr__(self, "entry_point", entry)
        object.__setattr__(
            self,
            "output_style",
            OutputStyle.DESTINATION if destination else OutputStyle.RETURN,
        )
        if self.source_path not in self.source_files:
            raise ValueError(f"missing entry source: {self.source_path}")
        nonempty(self.source_files[self.source_path], "bundle entry source")

    @property
    def source_path(self) -> str:
        path = self.entry_point.split("::")[0]
        return (
            f"{BUNDLE_SOLUTION}/{path}" if BUNDLE_CONFIG in self.source_files else path
        )

    @property
    def symbol(self) -> str:
        return self.entry_point.split("::")[1]

    @classmethod
    @agent_function
    def from_sources(
        cls,
        source_files: Mapping[str, str],
        problem: ProblemSpec,
        *,
        name: str | None = None,
        build_root: Path = BUILD_DIRECTORY,
        include_paths: Sequence[Path] = (),
    ) -> Kernel:
        """Construct and build a callable kernel from its complete sources."""
        kernel = cls(name or problem.name, problem, source_files)
        kernel.build(build_root, include_paths=include_paths)
        return kernel

    @agent_function
    def build(
        self,
        build_root: Path = BUILD_DIRECTORY,
        *,
        include_paths: Sequence[Path] = (),
        strides: Mapping[tuple[str, str], tuple[int, ...]] | None = None,
    ):
        """Build in this process; serialized kernels contain no runtime handles."""
        object.__setattr__(self, "function", None)
        from klineage.artifact.bundle import BundleLoader

        function = BundleLoader(build_root, include_paths=include_paths).build(
            self, strides=strides
        )
        object.__setattr__(self, "function", function)

    def __call__(self, *inputs: Any) -> Any:
        if self.function is None:
            raise RuntimeError("Kernel is not built; use from_sources() or build()")
        return self.function(*inputs)

    @property
    def fingerprint(self) -> str:
        value = {
            "problem": self.problem.to_dict(),
            "definition_io": [
                list(self.problem.definition[role]) for role in ("inputs", "outputs")
            ],
            "source_files": dict(sorted(self.source_files.items())),
        }
        return hashlib.sha256(
            json.dumps(
                value, ensure_ascii=False, sort_keys=True, separators=(",", ":")
            ).encode()
        ).hexdigest()

    def to_dict(self) -> dict[str, Any]:
        """Serialize sources, problem, and validation; omit compiled runtime handles."""
        payload = {
            "name": self.name,
            "problem": self.problem.to_dict(),
            "source_files": dict(sorted(self.source_files.items())),
            "validation": self.validation.to_dict() if self.validation else None,
        }
        if self.compile_flags:
            payload["compile_flags"] = list(self.compile_flags)
        return payload

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> Kernel:
        """Restore serialized Kernel metadata without building or executing sources."""
        validation = value.get("validation")
        return cls(
            name=value["name"],
            problem=ProblemSpec.from_dict(mapping(value["problem"], "kernel problem")),
            source_files=mapping(value["source_files"], "kernel source_files"),
            compile_flags=tuple(value.get("compile_flags") or ()),
            validation=ValidationResult.from_dict(
                mapping(validation, "kernel validation")
            )
            if validation is not None
            else None,
        )


@agent_function
def save_kernel(kernel: Kernel, workdir: Path) -> None:
    """Write kernel.json in an existing workdir, replacing its prior metadata.

    Serializes the Kernel's sources, problem, and validation; it does not reread
    edited disk sources or compile. Reconstruct the Kernel after source edits.
    """
    path = workdir / KERNEL_FILE
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(kernel.to_dict(), ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    temporary.replace(path)


@agent_function
def load_kernel(workdir: Path) -> Kernel:
    """Restore kernel.json from a directory without compiling or running it.

    Returns a Kernel with embedded sources and problem. Evaluation builds it in
    a worker; call Kernel.build before direct execution in this process.
    """
    return Kernel.from_dict(
        json.loads((workdir / KERNEL_FILE).read_text(encoding="utf-8"))
    )


__all__ = ["Kernel", "ValidationResult", "load_kernel", "save_kernel"]

"""Build native bundles and isolate Python bundle imports."""

from __future__ import annotations

import fcntl
import hashlib
import importlib.util
import json
import sys
import threading
from collections.abc import Callable, Mapping, Sequence
from contextlib import contextmanager
from pathlib import Path
from types import ModuleType
from typing import TYPE_CHECKING, Any, TypeGuard

from klineage.artifact.source import snapshot
from klineage.artifact.tensor import BundleCallable
from klineage.backend import Backend, get_backend, platform_backend
from klineage.constants import BUNDLE_CONFIG, BUNDLE_SOLUTION, MODULE_HASH_LENGTH
from klineage.contract import OutputStyle, ValueRole

if TYPE_CHECKING:
    from klineage.artifact.kernel import Kernel

#: Serialize temporary module/environment changes within this process.
IMPORT_LOCK = threading.RLock()
#: Mutable source staging directory used by compilers.
BUILD_SOURCES = "sources"
#: File lock covering source staging and compilation across processes.
BUILD_LOCK = ".klineage-build.lock"


@contextmanager
def source_import_scope(root: Path, modules: dict[str, ModuleType]):
    """Prevent ordinary local imports from leaking between two artifacts."""

    with IMPORT_LOCK:
        local_names = local_top_level_names(root)
        displaced = {
            name: module
            for name, module in tuple(sys.modules.items())
            if name in modules or name.split(".", 1)[0] in local_names
        }
        for name in displaced:
            sys.modules.pop(name, None)
        before = set(sys.modules)
        previous = sys.dont_write_bytecode
        sys.dont_write_bytecode = True
        sys.modules.update(modules)
        sys.path.insert(0, str(root))
        try:
            yield
        finally:
            sys.dont_write_bytecode = previous
            try:
                sys.path.remove(str(root))
            except ValueError:
                pass
            for name in set(sys.modules) - before:
                module = sys.modules.get(name)
                if module_is_under(module, root):
                    modules[name] = module
                    sys.modules.pop(name, None)
            sys.modules.update(displaced)


def local_top_level_names(root: Path) -> set[str]:
    names = {path.stem for path in root.glob("*.py") if path.name != "__init__.py"}
    # Directories without __init__.py are importable namespace packages too.
    names.update(path.name for path in root.iterdir() if path.is_dir())
    return names


def module_is_under(module: ModuleType | None, root: Path) -> TypeGuard[ModuleType]:
    if module is None:
        return False
    filename = getattr(module, "__file__", None)
    locations = (filename,) if filename else getattr(module, "__path__", ())
    try:
        return any(Path(path).resolve().is_relative_to(root) for path in locations)
    except (OSError, RuntimeError, ValueError):
        return False


class BundleLoader:
    def __init__(self, build_root: Path, *, include_paths: Sequence[Path] = ()):
        self.build_root = Path(build_root).resolve()
        self.include_paths = tuple(Path(path).resolve() for path in include_paths)
        self.modules: dict[str, Any] = {}

    def build(
        self,
        kernel: Kernel,
        *,
        strides: Mapping[tuple[str, str], tuple[int, ...]] | None = None,
    ) -> Callable[..., Any]:
        function = self.load(kernel)
        if (
            kernel.language == "python"
            and kernel.output_style is OutputStyle.RETURN
            and strides is None
        ):
            return function
        return BundleCallable(kernel.problem, function, kernel.output_style, strides)

    def load(self, kernel: Kernel) -> Callable[..., Any]:
        if BUNDLE_CONFIG in kernel.source_files and kernel.language == "python":
            backend = platform_backend(kernel.problem.platform)
            if backend is not None:
                backend.prepare()
            root = Path(snapshot(self.build_root, kernel.source_files))
            return self.load_python(root, kernel)

        backend = get_backend(kernel.problem.language, kernel.problem.platform)
        if BUNDLE_CONFIG not in kernel.source_files:
            if set(kernel.source_files) != {backend.raw_source}:
                raise ValueError(
                    f"raw {backend.kind} adapters require a single {backend.raw_source} source"
                )
            sources = {
                backend.raw_source: kernel.source_files[backend.raw_source],
                "binding.cpp": backend.binding(),
            }
            native_root = Path(snapshot(self.build_root, sources))
            module = self.load_native(
                native_root, sources, backend, kernel.compile_flags
            )
            launch = getattr(module, "launch", None)
            if not callable(launch):
                raise TypeError("native extension did not expose launch")
            input_count = len(kernel.problem.values(ValueRole.INPUTS))

            def run(*tensors):
                launch(list(tensors[:input_count]), list(tensors[input_count:]))

            return run
        root = Path(snapshot(self.build_root, kernel.source_files))
        module = self.load_native(
            root, kernel.source_files, backend, kernel.compile_flags
        )
        return self.entry(module, kernel.symbol)

    def load_python(self, root: Path, kernel: Kernel) -> Callable[..., Any]:
        name = f"_klineage_kernel_{kernel.fingerprint[:MODULE_HASH_LENGTH]}"
        spec = importlib.util.spec_from_file_location(name, root / kernel.source_path)
        if spec is None or spec.loader is None:
            raise ImportError(f"cannot load Python entry {kernel.source_path!r}")
        module = importlib.util.module_from_spec(spec)
        modules = {name: module}
        directory = root / BUNDLE_SOLUTION
        with source_import_scope(directory, modules):
            spec.loader.exec_module(module)
            function = self.entry(module, kernel.symbol)

        # Delayed imports need the same private modules as initial imports.
        def run(*args):
            with source_import_scope(directory, modules):
                return function(*args)

        return run

    @staticmethod
    def entry(module: Any, symbol: str) -> Callable[..., Any]:
        function = getattr(module, symbol)
        if not callable(function):
            raise TypeError(f"bundle entry point {symbol!r} is not callable")
        return function

    def load_native(
        self,
        root: Path,
        source_files: Mapping[str, str],
        backend: Backend,
        compile_flags: Sequence[str] = (),
    ):
        native_files = {
            path: source
            for path, source in source_files.items()
            if path != BUNDLE_CONFIG and Path(path).suffix != ".py"
        }
        sources = [
            path
            for path in sorted(native_files)
            if Path(path).suffix in backend.native_suffixes
        ]
        if not sources:
            raise ValueError(f"{backend.kind} build requires native source files")
        include_paths = [str(root / BUNDLE_SOLUTION), *map(str, self.include_paths)]

        with IMPORT_LOCK:
            options = backend.build_options(compile_flags=compile_flags)
            # Cache complete sources, flags, includes, and architecture together.
            digest = hashlib.sha256(
                json.dumps(
                    [backend.kind, native_files, options, include_paths],
                    sort_keys=True,
                ).encode()
            ).hexdigest()[:MODULE_HASH_LENGTH]
            name = f"klineage_{backend.kind}_{digest}"
            if name in self.modules:
                return self.modules[name]
            directory = self.build_root / name
            directory.mkdir(parents=True, exist_ok=True)
            # Compilers may write beside inputs; frozen snapshots stay read-only.
            with native_sources(directory, native_files) as compile_root:
                sources = [str(compile_root / path) for path in sources]
                include_paths[0] = str(compile_root / BUNDLE_SOLUTION)
                module = backend.compile(
                    name, sources, directory, include_paths, options
                )
            self.modules[name] = module
            return module


@contextmanager
def native_sources(directory: Path, sources: Mapping[str, str]):
    # Lock staging as well as compilation across worker processes.
    with (directory / BUILD_LOCK).open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        root = directory / BUILD_SOURCES
        for name, source in sources.items():
            target = root / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(source.encode("utf-8"))
        yield root

"""Adapt bundle calls to the problem's tensor ABI."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import TYPE_CHECKING, Any

from klineage.backend import Backend, get_backend
from klineage.contract import ABIValue, OutputStyle, ProblemSpec, ValueRole

if TYPE_CHECKING:
    import torch

#: Accepted ABI dtype spellings mapped to PyTorch names.
DTYPE_ALIASES = {
    "bool": "bool",
    "bfloat16": "bfloat16",
    "bf16": "bfloat16",
    "float16": "float16",
    "half": "float16",
    "float32": "float32",
    "float": "float32",
    "float64": "float64",
    "double": "float64",
    "int8": "int8",
    "uint8": "uint8",
    "int16": "int16",
    "short": "int16",
    "int32": "int32",
    "int": "int32",
    "int64": "int64",
    "long": "int64",
}


class BundleCallable:
    def __init__(
        self,
        problem: ProblemSpec,
        function: Any,
        style: OutputStyle,
        strides: Mapping[tuple[str, str], tuple[int, ...]] | None = None,
    ):
        self.inputs = tensor_values(problem, ValueRole.INPUTS)
        self.outputs = tensor_values(problem, ValueRole.OUTPUTS)
        self.backend = get_backend(problem.language, problem.platform)
        self.function, self.style = function, style
        self.strides = strides or {}

    def __call__(self, *inputs: torch.Tensor):
        if len(inputs) != len(self.inputs):
            raise ValueError("bundle input count does not match its ABI")
        tensors = tuple(
            check_tensor(
                value,
                spec,
                "input",
                self.strides.get(("input", spec.name)),
                backend=self.backend,
            )
            for value, spec in zip(inputs, self.inputs, strict=True)
        )
        device = tensors[0].device if tensors else self.backend.device()
        if any(value.device != device for value in tensors):
            raise ValueError("bundle inputs must share a device")

        # The evaluator supplies trailing destinations; return-style entries own allocation.
        with self.backend.runtime().device(device):
            if self.style is OutputStyle.DESTINATION:
                outputs = tuple(
                    allocate(spec, device, self.strides.get(("output", spec.name)))
                    for spec in self.outputs
                )
                self.function(*tensors, *outputs)
            else:
                result = self.function(*tensors)
                outputs = (result,) if len(self.outputs) == 1 else result
                if not self.outputs and result is None:
                    outputs = ()
                if (
                    not isinstance(outputs, Sequence)
                    or isinstance(outputs, (str, bytes))
                    or len(outputs) != len(self.outputs)
                ):
                    raise ValueError("bundle output count does not match its ABI")

            for value, spec in zip(outputs, self.outputs, strict=True):
                check_tensor(
                    value,
                    spec,
                    "output",
                    self.strides.get(("output", spec.name)),
                    backend=self.backend,
                )
                if value.device != device:
                    raise ValueError("bundle outputs must use the input device")
        if not outputs:
            return None
        return outputs[0] if len(outputs) == 1 else tuple(outputs)


def tensor_values(problem: ProblemSpec, role: ValueRole) -> tuple[ABIValue, ...]:
    values = problem.values(role)
    if any(problem.definition[role][value.name]["shape"] is None for value in values):
        raise TypeError("tensor entries do not support scalar arguments or outputs")
    return values


def check_tensor(
    value: Any,
    spec: ABIValue,
    role: str,
    stride: tuple[int, ...] | None = None,
    *,
    backend: Backend,
) -> torch.Tensor:
    tensor = require_tensor(value, f"ABI {role} {spec.name!r}", backend)
    if tensor.dtype != tensor_dtype(spec.dtype):
        raise ValueError(f"ABI {role} {spec.name!r} has the wrong dtype")
    if tuple(tensor.shape) != spec.shape:
        raise ValueError(f"ABI {role} {spec.name!r} has the wrong shape")
    if stride is not None and tuple(tensor.stride()) != tuple(stride):
        raise ValueError(f"ABI {role} {spec.name!r} has the wrong stride")
    return tensor


def allocate(
    spec: ABIValue,
    device: torch.device,
    stride: tuple[int, ...] | None = None,
) -> torch.Tensor:
    import torch

    shape = fixed_shape(spec)
    if stride is None:
        return torch.empty(shape, dtype=tensor_dtype(spec.dtype), device=device)
    return torch.empty_strided(
        shape,
        tuple(int(value) for value in stride),
        dtype=tensor_dtype(spec.dtype),
        device=device,
    )


def fixed_shape(spec: ABIValue) -> tuple[int, ...]:
    if any(isinstance(value, str) for value in spec.shape):
        raise ValueError(f"output {spec.name!r} must have a fixed shape")
    return tuple(int(value) for value in spec.shape)


def tensor_dtype(value: str | None) -> torch.dtype:
    import torch

    if value is None:
        raise ValueError("ABI values require a dtype")
    name = value.lower().removeprefix("torch.")
    try:
        return getattr(torch, DTYPE_ALIASES[name])
    except KeyError as exc:
        raise ValueError(f"unsupported tensor dtype {value!r}") from exc


def require_tensor(value: Any, label: str, backend: Backend) -> torch.Tensor:
    torch = backend.torch()
    if not isinstance(value, torch.Tensor):
        raise TypeError(f"{label} must be a torch.Tensor")
    if value.device.type != backend.device_type:
        raise ValueError(f"{label} must be on {backend.device_type}")
    backend.validate_tensor(value)
    return value
