#include <cuda_fp16.h>
#include <cstdint>
#include <torch/extension.h>
__global__ void smem_bw(float* out, int iters, int mode) {
  extern __shared__ __align__(1024) uint4 sm[];
  int tid = threadIdx.x;
  if (tid < 256) sm[tid] = make_uint4(tid, tid+1, tid+2, tid+3);
  __syncthreads();
  uint32_t acc = 0;
  int base = (threadIdx.x * 4) & 1023;
  if (mode == 0) {                    // 16B per lane
    for (int i = 0; i < iters; i++) {
      uint4 v = sm[(base + i) & 1023];
      acc += v.x + v.y + v.z + v.w;
    }
  } else if (mode == 1) {             // 4B per lane
    for (int i = 0; i < iters; i++) {
      uint32_t v = ((const uint32_t*)sm)[(base + i) & 4095];
      acc += v;
    }
  } else {                            // ldmatrix.x4
    uint32_t d0, d1, d2, d3;
    for (int i = 0; i < iters; i++) {
      uint32_t addr = (uint32_t)__cvta_generic_to_shared(&sm[(base + (threadIdx.x & 7) + i) & 1023]);
      asm volatile(\"ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\"
                   : \"=r\"(d0), \"=r\"(d1), \"=r\"(d2), \"=r\"(d3) : \"r\"(addr));
      acc += d0 + d1 + d2 + d3;
    }
  }
  if (acc == 0xdeadbeef) out[0] = (float)acc;
}
torch::Tensor run_bw(int64_t blocks, int64_t threads, int64_t iters, int64_t mode) {
  auto out = torch::zeros({1}, torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA));
  cudaFuncSetAttribute(smem_bw, cudaFuncAttributeMaxDynamicSharedMemorySize, 32*1024);
  smem_bw<<<(int)blocks, (int)threads, 32*1024>>>(out.data_ptr<float>(), (int)iters, (int)mode);
  auto err = cudaDeviceSynchronize(); TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
  return out;
}
